UPDATE fin_petty_expense_types SET spec = '{"item_based": true, "item_label": "รายการปะ/เปลี่ยนยาง", "header_fields": [{"key": "payee_name", "label": "จ่ายให้ (ร้าน/ผู้รับเงิน)", "type": "text", "required": true}, {"key": "payment_method", "label": "วิธีจ่าย", "type": "select", "options": ["โอนเงิน", "เงินสด"], "required": true}, {"key": "payee_type", "label": "ผู้รับเงิน", "type": "select", "options": ["ร้านจดทะเบียน", "บุคคล/ร้านเงินสด"], "required": true}], "item_fields": [{"key": "event_date", "label": "วันที่ตามบิล", "type": "date", "required": true}, {"key": "truck", "label": "รถ", "type": "truck", "required": true, "search": ["code", "plate"]}, {"key": "truck_type", "label": "ประเภทรถ", "type": "select", "options": ["โม่ใหญ่", "โม่เล็ก", "12 ตัน", "หัวลาก", "อื่นๆ"], "required": true, "auto_from": "truck"}, {"key": "driver_name", "label": "พจส.", "type": "text", "required": false}, {"key": "ref_no", "label": "เลขที่บิล/ใบเสร็จร้าน", "type": "text", "required": true}, {"key": "remark", "label": "รายการที่ทำ", "type": "text", "required": true}, {"key": "qty", "label": "จำนวน (เส้น)", "type": "number", "required": true}, {"key": "rate", "label": "ราคา/เส้น", "type": "money", "required": true}], "attachments": [{"key": "receipt", "label": "บิลเงินสด/ใบเสร็จร้าน", "required": true, "max": 10}, {"key": "photo", "label": "รูปยางที่เปลี่ยน", "required": true, "max": 10}, {"key": "id_card", "label": "สำเนาบัตรประชาชนผู้รับเงิน (เมื่อโอนเข้าชื่อบุคคล/ร้านเงินสด)", "required": false, "max": 3}, {"key": "transfer", "label": "หลักฐานโอนเงิน", "required": true, "max": 3}], "rules": [{"when": "total >= 500", "require_field": "dd_no", "at": "BEFORE_SUBMIT_TO_ACCOUNTING"}, {"when": "always", "require_attachment": "receipt", "at": "BEFORE_APPROVE"}, {"when": "always", "require_attachment": "transfer", "at": "BEFORE_APPROVE"}, {"when": "payment_method == โอนเงิน && payee_type == บุคคล/ร้านเงินสด", "require_attachment": "id_card", "at": "BEFORE_APPROVE"}, {"when": "always", "require_attachment": "photo", "at": "BEFORE_APPROVE"}], "duplicate_check": {"scope": "item", "hard": {"keys": ["ref_no", "truck_code", "truck_plate"], "days": 365, "action": "block", "override": false}, "soft": {"keys": ["event_date", "truck"], "days": 7, "action": "warn", "override": "reason"}}, "print": {"unit": "เส้น"}, "prints": ["PETTY_VOUCHER", "DD"], "atms": {"sku": "LB00009", "product_group": "ค่าแรง-ระบบยาง", "unit": "งาน", "vat": 0}}'::jsonb WHERE code = 'TIRE';
