], "duplicate_check": {"scope": "item", "hard": {"keys": ["ref_no", "truck_code", "truck_plate"], "days": 365, "action": "block", "override": false}, "soft": {"keys": ["event_date", "truck"], "days": 7, "action": "warn", "override": "reason"}}, "print": {"unit": "คัน"}, "prints": ["PETTY_VOUCHER", "RECEIPT_SUBSTITUTE", "DD"]}'::jsonb WHERE code = 'REPAIR';
UPDATE fin_petty_expense_types SET spec = '{"item_based": false, "header_fields": [{"key": "event_date", "label": "วันที่ใช้ทาง", "type": "date", "required": true}, {"key": "payee_name", "label": "ผู้สำรองจ่าย", "type": "employee", "required": true}, {"key": "truck", "label": "รถ", "type": "truck", "required": true, "search": ["code", "plate"]}, {"key": "driver", "label": "พจส.", "type": "employee", "required": true}, {"key": "route_from", "label": "ขึ้นด่าน", "type": "text", "required": true}, {"key": "route_to", "label": "ลงด่าน", "type": "text", "required": true}, {"key": "receipt_no", "label": "เลขที่ใบเสร็จ", "type": "text", "required": false}, {"key": "rate", "label": "จำนวนเงิน", "type": "money", "required": true}], "attachments": [{"key": "receipt", "label": "ใบเสร็จค่าทางด่วน (ตัวจริง)", "required": true, "max": 10, "note": "สแกนหรือถ่ายแนบที่นี่ แล้วส่งตัวจริงไปกับใบปะหน้า"}, {"key": "transfer", "label": "หลักฐานโอนเงิน", "required": true, "max": 3}, {"key": "map", "label": "รูป Map / เส้นทาง", "required": false, "max": 3}, {"key": "other", "label": "อื่นๆ", "required": false, "max": 3}], "rules": [{"when": "total >= 500", "require_field": "dd_no", "at": "BEFORE_SUBMIT_TO_ACCOUNTING"}, {"when": "always", "require_attachment": "receipt", "at": "BEFORE_APPROVE"}, {"when": "always", "require_attachment": "transfer", "at": "BEFORE_APPROVE"}], "duplicate_check": {"scope": "item", "hard": {"keys": ["ref_no", "truck_code", "truck_plate"], "days": 365, "action": "block", "override": false}, "soft": {"keys": ["event_date", "truck"], "days": 7, "action": "warn", "override": "reason"}}, "print": {"unit": "เที่ยว"}, "prints": ["PETTY_VOUCHER", "DD"]}'::jsonb WHERE code = 'TOLL';
UPDATE fin_petty_expense_types SET spec = '{"item_based": false, "header_fields": [{"key": "event_date", "label": "วันที่เดินทาง", "type": "date", "required": true}, {"key": "payee_name", "label": "ผู้เดินทาง (สำรองจ่าย)", "type": "employee", "required": true}, {"key": "dept", "label": "แผนกผู้ขอ", "type": "select", "options": ["จัดส่ง", "ยานยนต์", "จป.", "HR", "บัญชี", "จัดซื้อ", "เชื้อเพลิง"], "required": true}, {"key": "service", "label": "บริการ", "type": "select", "options": ["Grab", "Taxi"], "required": true}, {"key": "leg", "label": "เที่ยว", "type": "select", "options": ["ขาไป", "ขากลับ"], "required": true}, {"key": "route_from", "label": "จาก", "type": "text", "required": true}, {"key": "route_to", "label": "ไป", "type": "text", "required": true}, {"key": "reason", "label": "เหตุที่ใช้", "type": "text", "required": true}, {"key": "ref_no", "label": "Trip Code / รหัสการเดินทาง", "type": "text", "required": false}, {"key": "truck", "label": "รถที่เกี่ยวข้อง", "type": "truck", "required": false, "search": ["code", "plate"]}, {"key": "rate", "label": "จำนวนเงิน", "type": "money", "required": true}, {"key": "toll_amount", "label": "ค่าทางด่วน (ถ้ามี รวมในใบเดียว)", "type": "money", "required": false}], "attachments": [{"key": "request_form", "label": "แบบฟอร์มขอใช้บริการที่อนุมัติแล้ว", "required": true, "max": 3}, {"key": "receipt", "label": "ใบเสร็จ/E-Receipt หรือรูปมิเตอร์+บัตรคนขับ", "required": true, "max": 10}, {"key": "transfer", "label": "หลักฐานโอนเงิน", "required": true, "max": 3}, {"key": "map", "label": "รูป Map / เส้นทาง", "required": false, "max": 3}, {"key": "other", "label": "อื่นๆ", "required": false, "max": 3}], "rules": [{"when": "total >= 500", "require_field": "dd_no", "at": "BEFORE_SUBMIT_TO_ACCOUNTING"}, {"when": "always", "require_attachment": "request_form", "at": "BEFORE_APPROVE"}, {"when": "always", "require_attachment": "receipt", "at": "BEFORE_APPROVE"}, {"when": "always", "require_attachment": "transfer", "at": "BEFORE_APPROVE"}], "duplicate_check": {"scope": "item", "hard": {"keys": ["ref_no", "truck_code", "truck_plate"], "days": 365, "action": "block", "override": false}, "soft": {"keys": ["event_date", "driver"], "days": 7, "action": "warn", "override": "reason"}}, "print": {"unit": "เที่ยว"}, "prints": ["PETTY_VOUCHER", "RECEIPT_SUBSTITUTE", "DD", "REQUEST_FORM"]}'::jsonb WHERE code = 'TRAVEL';
